quests[72372] = { id = 72372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Dragon...kin", objectives = "The blood of the dragon has touched many creatures in this land. Though not all of them can be reasoned with, that does not preclude them from becoming stalwart companions.\n\nThere is a deep bond that one must build when befriending dragonkin. Of course it comes naturally to my kind, but I can give you a book that will teach you our methods.\n\nAfter that, it is up to you to achieve the bond needed to keep them by your side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72373] = { id = 72373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: The Hunt is On", description = "Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause.\n\nWhilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts.\n\nThere is much to be done. Best not delay.", progress = "Has our renowned traveler returned with more news of success?", completion = "Oh my. You did all of that and return in one piece? Quite impressive.\n\nPlease accept this as a token of our appreciation.", objectives = "Assist the Maruuk on a Hunt within the Dragon Isles. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72374] = { id = 72374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Dragonbane Keep", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nA lingering djaradin threat moves upon the Waking Shores deep within the smoldering inferno of Dragonbane Keep. We must move to disrupt their advances.\n\nWe await your return, {name}.", progress = "Do you bring news of your success?", completion = "My, my. What wondrous news! The Accord will be most pleased by your efforts. \n\nPlease accept this as a token of our gratitude.", objectives = "Travel to The Waking Shores and lay siege to Dragonbane Keep. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72375] = { id = 72375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: The Isles Call", description = "Your actions have not gone unnoticed.\n\nAcross the Isles, our allies seek to ensure the safety of all who venture throughout these lands. There are, however, some who would seek to end your... work, as it impedes in their plans.\n\nDo what you must to ensure our allies are protected.", progress = "Travels treating you well? Not too many enemies made along the way, I should hope.", completion = "Ah, you return! I should not act surprised, but alas, here we are.\n\nPlease accept this as a small token of our appreciation.", objectives = "Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72380] = { id = 72380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together We Are Unstoppable", description = "{name}, you must tell Alexstrasza and Nozdormu what has happened.\n\nKhadgar and I will meet you at the Seat of the Aspects momentarily.", progress = "What has happened, {name}?", completion = "We stand united against the Incarnates, {name}.\n\nTogether, we will protect this world.", objectives = "Return to the Seat of the Aspects and inform Alexstrasza about what happened after the defeat of Raszageth in the Vault of the Incarnates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72381] = { id = 72381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonscale Expedition", description = "Assist the Tortollan by completing 3 world quests.", sourceObjective = "Complete 3 Tortollan world quests.", sourceObjectiveStatus = "unverified-source-field" }
quests[72382] = { id = 72382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskaara Tuskarr", description = "Assist the Tortollan by completing 3 world quests.", sourceObjective = "Complete 3 Tortollan world quests.", sourceObjectiveStatus = "unverified-source-field" }
