quests[72395] = { id = 72395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Friend, your help has been invaluable in helping out our community and people. We've put together additional supplies for you and hope you are able to continue to help us!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72396] = { id = 72396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horns of Plenty", description = "Many of our inventions rely on using a sturdy and springy material. Fortunately, vorquin horns have served as the perfect product for many of our modern creations.\n\nEven more fortunate for us, the Dragon Isles are swarmed with vorquin. It should be a simple task for you to gather some springy horns from the vorquin for us.", progress = "Did you collect the vorquin horns?", completion = "Our engineers will be thrilled to have more materials. Thank you for your contributions.", objectives = "Gather 20 Springy Horns from the vorquin of the Dragon Isles for Dothenos of the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72397] = { id = 72397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientation: Dragonscale Basecamp", progress = "Welcome to camp, {name}!", completion = "Met me Granpap, did ye?\n\nWell, don't believe all his stories... He loves to brag about the family!", objectives = "Meet the important suppliers in the Dragonscale Basecamp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72398] = { id = 72398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock and Stone", description = "Earth elementals in the Dragon Isles are composed of various rocks and minerals. Our blacksmiths are thoroughly fascinated with the unique tools they are able to manufacture from smelting such materials. In fact, they appear to have smelted the last of their samples.\n\nI would hate to ruin their fun. Would you mind replenishing the supply?", progress = "Have you gathered enough Earthen Samples from the Elementals?", completion = "Ah, the blacksmiths will be pleased with these samples.", objectives = "Gather 15 Earthen Samples from the earth elementals of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72399] = { id = 72399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit's Garden", description = "Our parents always say we shouldn't visit the gardens above Gelikyr. They think the gardener is mean and dangerous. \n\nThat's not true, though! They're a bit grumpy, but they're really nice! \n\nNone of us have been up there since the Primalists showed up. It's way too dangerous now. Still, I hope the gardener is okay. Could you go and check on them, since we can't visit anymore?", completion = "You'd better not have trampled any of my plants with those clumsy stompers of yours. Now, what do you want from me?", objectives = "Speak to Szareth in Shadow Ledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72405] = { id = 72405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unlikely Informant", description = "This is a top secret mission, {name}.\n\nWe've had a break in.\n\nA powerful historical artifact was stolen from the Keep... and it looks like the Defias Brotherhood is to blame. We caught one thief, but the other got away.\n\nBut I don't like it, {name}... my gut tells me there's more. \n\nI've called in a... specialist on the Brotherhood. Meet us in the basement of the Lion's Pride Inn in Goldshire.", progress = "We must recover what was stolen from the Keep, at all costs.", completion = "My few interactions with Vanessa told me she isn't interested in the banditry of the old Defias Brotherhood. To her, the Brotherhood meant supporting the downtrodden... those that Stormwind had left behind. \n\nThat, I can respect. \n\nBut most of her Brotherhood continue to engage in thievery from innocent travelers. That's not revolution, that's highway robbery.\n\nShe insists she tries to stop them.", objectives = "Meet Mathias Shaw in the basement of the Lion's Pride Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72406] = { id = 72406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientation: Valdrakken", progress = "Welcome Valdrakken, {name}.", completion = "On behalf of the Valdrakken Accord, we look forward to working with you, {name}.", objectives = "Meet the important Accord suppliers in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72407] = { id = 72407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soaked in Success", description = "Fishermen of our tribe are constantly plagued with waterlogged packs and boots. Lately, the riverbeasts have been swarming fishing spots and causing even more mayhem.\n\nThe hide of the riverbeasts are quite slick and water-resistant. Perhaps we can handle two problems at once. If you could help handle the over abundance of riverbeasts and bring back their hides, our fishers would be quite pleased.", progress = "Have you found some hide with waterproof qualities?", completion = "I am confident that these hides will do well to protect our equipment from further water damage. Thank you for your help.", objectives = "Gather 18 Waterproof Hide from the riverbeasts of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72408] = { id = 72408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Window to the Past", description = "In this, I trust Vanessa's word. I do not believe she knows what the Drakefire Amulet is. Some of the story about Onyxia was made public, but not all.\n\nPerhaps even you do not know. \n\nI will explain everything, for both of you.", progress = "<Vanessa sizes you up.>", completion = "We all have our own versions of the past, don't we? \n\nI don't care if some dragon lady had a magic amulet. It wasn't complete mind control. \n\nThe nobles already hated the common people. The Stonemason's Guild would never have needed to turn to banditry and become the Defias Brotherhood, if not for them.", objectives = "Speak with Shaw under the Lion's Pride Inn in Goldshire to hear about the history of the Drakefire Amulet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72409] = { id = 72409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotten Old Memories", description = "Whatever is going on, I don't like it. Last thing we need is this dragon lady's power corrupting everyone again. \n\nWhoever did this must have known much about Onyxia. Shaw mentioned this... Reginald Windsor. He was the only one to suspect Lady Prestor. Well, maybe his friends in the Burning Steppes have more of his information. \n\nShe must have had allies. Anything that points us to people close to her would help. \n\nCheck it out, will you?", progress = "Drink always seems to be empty... why's me drink always empty?", completion = "Ah, Windsor...", objectives = "Speak with Ragged John at Morgan's Vigil in the Burning Steppes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72410] = { id = 72410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pincers and Needles", description = "We've been running low on needles for tailoring lately. Those darn things keep snapping in two!\n\nSome pointy parts from the scythid in the area might serve as good replacements.", progress = "Have you found some pointy parts to replace our needles?", completion = "Great! Now the tailors can get back to work.", objectives = "Gather 10 Pointy Pincers from the scythid of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72411] = { id = 72411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cause Without a Rebel", description = "Good to see you again, {name}! Alexstrasza doesn't think we can stop the rebels effectively through force, despite the successes you've had.\n\nTo find other ways forward, Alexstrasza has called Maldra Flametongue here to talk about the rebellion and what drew her to it.\n\nPerhaps it would be helpful to join the conversation, and see what Maldra has to say. To avoid prying rebel eyes and ears, they will be meeting below us, on the second level of the Seat of the Aspects.", completion = "I've found the rebels are stockpiling a huge number of bombs beneath the Valdrakken aqueduct! We must stop them!", objectives = "Listen to Alexstrasza's conversation with Maldra Flametongue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72412] = { id = 72412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Interruption", description = "I managed to infiltrate a rebel camp, down in Scalewatch Cavern. It seemed like any other camp, except for frequent wagons coming into camp with their contents covered.\n\nEventually, I was able to discreetly make my way to where the wagons would be unloaded. The rebels are stockpiling bombs, but it's even worse!\n\nThey're piling the bombs against a pillar directly underneath the aqueduct from Tyrhold.\n\nMeet me down there, and we'll find a way to stop this!", completion = "We seem to be in time, {name} - let's put a stop to this before the aqueduct is destroyed!", objectives = "Meet Erima at Scalewatch Caverns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72413] = { id = 72413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irreconcilable Differences", description = "I wish we never had to raise arms against fellow dragonkin, {name}. We should be allies, not enemies. Unfortunately, their leader, Agitator Zoralek, made the choice for us when he threatened the aqueduct.\n\nFight your way inside the cave, and put a stop to Agitator Zoralek by any means necessary, before he can set off those bombs. Then bring back his detonator so we can secure it. Once we have that, the Scalesworn will be able to remove the bombs safely.", progress = "Were you able to stop Zoralek? Is the aqueduct safe?", completion = "By stopping Zoralek and retrieving his detonator, you've secured the aqueduct, for both Valdrakken and the life pools.", objectives = "Kill Agitator Zoralek and recover the detonator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72414] = { id = 72414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Prisoners!", description = "If Alexstrasza truly wants to find the causes of this rebellion, we need to hear out the rebels.\n   \nTo do that, we have to safely detain rebels who want to kill us. Well, you. That's much harder than resorting to violence, and more dangerous as well.\n\nBut I've experienced this when I left the rebels. Orian Darkwater cast a spell to bind me totally. It worked, and I paid close attention.\n\nI've imbued that spell into a ring. You can use it to bind them safely. It should work, anyway!", completion = "This is the more difficult way, but every rebel we capture instead of kill is a chance to end this violence - and a life saved.", objectives = "Use Maldra's Ring of Binding to detain 8 rebels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72415] = { id = 72415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebel Rousing Writings", description = "The rebels seem to have a lot of signs and flyers around the cave. They probably use it as a way to keep everyone aligned to their purpose, and motivated to fight.\n\nIt's hard to keep a large group united around a cause - especially if you use detestable methods like bombing civilians or destroying a water source - without a steady stream of reinforcement.\n\nLet's get a bunch of their propaganda. It may tell us a lot about what they're thinking, or who's telling them what to think.", progress = "Have you gotten a good sample of their writings?", completion = "These seem to mostly be written by Instigator Belaphon - I met her once, when I was in the rebellion. If we can find her, perhaps we can stop her from inciting so much anger! \n\nI'll also be able to look through these for any codes or ciphers from my rebel days they might still be using, to see if we can find out more. Good work, {name}!", objectives = "Gather 5 pieces of rebel propaganda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72416] = { id = 72416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporary Accommodations", description = "We've been sending the rebel prisoners to Steelcliff Rampart. It's the barracks where Valdrakken's city guard, the Scalesworn, are based.\n\nSo there are plenty of guards to keep them from causing harm or escaping.\n\nHead over there and we'll see what the next steps are in putting a permanent stop to this rebellion.", completion = "Thank you for coming, {name}. I am here to discuss with these prisoners why they wanted to rebel against the dragons. Please join me and we'll see what they have to say.", objectives = "Go to Steelcliff Rampart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72417] = { id = 72417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Persistent Dissidents", description = "My goal is to see this rebellion brought to an end, with as little violence as possible. To do that, I need to understand the root causes of this rebellion.\n\nThe rebels have clearly come to resent the Aspects and the dragonflights. And while we had to use force to protect Valdrakken, that hasn't brought about an end to the rebellion.\n\nI'd like you to speak to the prisoners, and ask why they rebelled. I'll accompany you to hear their reasons.", completion = "I might not agree with all their reasons - certainly not their violent methods - but I have a new understanding of why they want change.", objectives = "Ask 5 dragonkin why they rebelled.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72418] = { id = 72418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solicited Opinions", description = "That was enlightening, to say the least. The rebels we talked to had a lot to say which I wouldn't have anticipated.\n\nI have my thoughts on the situation, but what did you think of their grievances?\n\nAs neither a dragon nor dragonkin, you bring a certain objectivity to the matter.", progress = "Is there merit to what the dragonkin say, or only dereliction of duty?", completion = "I will consider your advice. Thank you again, {name}, for your aid.", objectives = "Discuss the rebels' grievances with Alexstrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72419] = { id = 72419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning up the Cliffraff", description = "{name}! Maldra has been going through the propaganda you retrieved, using ciphers she knew from her days as a rebel.\n\nShe found a coded message that led her to another rebel camp, where Belaphon is stirring up rebellion among anyone she can.\n\nMaldra and Inspector Erima are already there - go join them and let's see if we can finally put a stop to this rebellion!", completion = "The rebels are finding their way here from Scalewatch and other locations, based on the same ciphers Maldra found, {name}. Now there are far too many rebels for us to stop Belaphon without your help.", objectives = "Meet Maldra and Erima at the Rebellious Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72420] = { id = 72420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wreckonciliation", description = "Captain Drine informed me that Alexstrasza wants this done as peacefully as possible. And I've heard Alexstrasza is considering granting the Dragonkin more rights. Or even freedom.\n\nInstead of fighting our way through all these rebels when peace may be on the horizon, let's spread the word! Tell the dragonkin here that things are changing. Perhaps some will lay down their arms or choose to leave.\n\nBut be prepared to deal with those who insist on fighting.", progress = "Remember, each dragonkin you convince is a life you've saved.", completion = "That's great that so many stopped fighting! Too bad for those who didn't, but if you'd told me a camp full of rebels was largely going to lay down their arms, I wouldn't have believed it. Alexstrasza will be pleased, {name}!", objectives = "Inform 12 dragonkin of Alexstrasza's planned changes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72421] = { id = 72421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quill to Power", description = "{name}, we need to stop the quills from inciting the rebels long enough for us to be heard. \n\nTheir leader, Belaphon, seems to be giving the quills a degree of autonomy with that glowing staff. Gather up as many as you can, so they can't keep reproducing her words.\n\nOnce they're out of commission, we'll confront her directly - but we don't want the quills to scatter and continue spreading these messages.", progress = "How many quills have you found, {name}?", completion = "If we didn't gather up those quills, they'd keep inciting dragonkin, and we'd keep having more rebels to deal with. Thank you for putting a stop to them.", objectives = "Gather 6 enchanted quills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72422] = { id = 72422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Presses", description = "This is it, {name}. As the one propagating the ideas that drive the rebellion, if we can stop Belaphon, we'll see the end of the rebellion.\n\nTry to bind her with my ring, though you'll likely need to weaken her first. If she's willing to surrender, we'll bring her to Alexstrasza.\n\nI imagine the Queen of Dragons will have a lot of very choice words when they meet.", progress = "What word of the rebel leader, Belaphon?", completion = "Thank you, {name} - you've aided us in opposing this rebellion from the beginning. Now Valdrakken is safe, and more importantly, I will see that the dragonkin are treated with the respect they deserve.", objectives = "Instigator Belaphon defeated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72423] = { id = 72423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weathering the Storm", description = "Ah, you have arrived just in time! We've heard tales that the Nokhud centaur have powerful, dangerous weaponry infused with storm enchantments. We would like to bring some samples to our enchanters for study.\n\nAt the very least, we can decommission the weapons and put them to better use.", progress = "Have you found any weapons for study?", completion = "With these weapons no longer in destructive hands, we can feel more at peace and begin to understand these enchantments.", objectives = "Gather 12 Tempest Armaments from the Nokhud centaurs of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72424] = { id = 72424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Something Specific", description = "<Ragged John blinks blearily up at you.> \n\nSo ye took down that ol' worg, didye? Well aren't ye the biggest strongest human I seen since ol' Windsor. \n\n<Ragged John sighs.>\n\n...Well? What're ye still doing here? Go take what ye found to whoever sent ye here in the first place!", completion = "Ragged John is still around, is he? Been a while since I sent some agents to check up on him. He's a good man, under it all. \n\nNow, what are these notes? Hmmm... a Clessington?", objectives = "Return to Shaw in the basement of the Lion's Pride Inn.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72426] = { id = 72426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Clessington Estate", description = "Excellent, {name}. Finally, something we can work with. \n\nCount Clessington is a member of the House of Nobles and a powerful mage. He has fallen on hard times since Anduin cracked down on corruption in Stormwind.\n\nI would not put it past him to have something to do with this.\n\nHe recently purchased an old manor in Duskwood. I will contact my sources and see what other information I can find. You and Vanessa should go to the manor and investigate.", progress = "Did you feel that? \n\nThis place is creepy. I swear every now and then something brushes by me. The hairs on the back of my neck keep going straight up!", completion = "You have my deepest apologies, friend, for the behavior of my \"attendants\". \n\nThough, I suppose they were never mine. They're my father's. Likely sent with me to keep me out of his way while he does something terrible. \n\nI had hoped it wouldn't come to this. I'm so sorry. Please, let me help you stop him.", objectives = "Investigate the manor at Raven Hill in Duskwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72427] = { id = 72427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animated Infusion", description = "I have a simple request for you today.\n\nThe alchemists are short on an ingredient used in a particularly tricky brew. The herb is easy enough to retrieve. You'll just need to find some aggressive plants to extract samples from. Think you can handle that?", progress = "Have you retrieved the herbs?", completion = "Well, not all hunts will be the most exhilarating. Nonetheless, the samples you retrieved will be put to good use.", objectives = "Gather 13 Spiked Leaves from the lashers of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72428] = { id = 72428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornswog Hoarders", description = "It's no secret that the hornswogs in these lands have a fascination for gems, jewels, and all things shiny. Why, even the other day I found a very rare jewel in some hornswog droppings!\n\nWell, it might not be the most appealing task, but it seems the hornswog have a habit of not only collecting, but also consuming valuables.", progress = "Were you able to find some gems?", completion = "Well these gems don't smell very delightful... We'll get to cleaning them up right away.", objectives = "Gather 20 Pungent Gems from the hornswog of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72429] = { id = 72429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientation: Maruukai", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nThe Maruuk as a people are not staunchly against outsiders, but we do require any potential allies to prove their worth. As you meet the clans and aid in our ventures, word will spread of your support.\n\nOn the lower level of the krutal on the hill you will find one of the Khanam Matra's daughters, who can help you see where you stand with our people. Be sure to introduce yourself.", progress = "I look forward to seeing how you contribute to the Maruuk.", completion = "I look forward to seeing how you contribute to the Maruuk.", objectives = "Meet the Keeper of Renown and Renown Quartermaster in Maruukai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72430] = { id = 72430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Misdeeds in Moonbrook", description = "Moonbrook? What is this Count Clessington doing at my home?!\n\nIt can't be anything good. I'll signal Shaw.\n\n<Vanessa glances at Cecilia Clessington.>\n\nShe might make for a good hostage. Let's bring the rich girl, too.\n\nMeet us there.", completion = "Why is it... so empty?", objectives = "Meet Vanessa and Shaw in Moonbrook in Westfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72431] = { id = 72431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hungry Heritage", description = "It's been a while since I've been home. \n\nSomething isn't right. My people should be here. \n\nI'm going in... but I won't turn down some back up. \n\n... I never should've left for so long.", completion = "How dare they!", objectives = "Investigate the Defias Hideout in Moonbrook with Vanessa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72432] = { id = 72432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Only the Finest Goons", description = "These \"attendants\" of my father's attacked us the moment we arrived!\n\nThese are certainly not the kindly servants I had as a child. These are hired killers!\n\nIf my father is planning what I think he's planning... we can't let them do this. They will kill everyone in their way.\n\n<Cecilia winces.>\n\nIf it's kill or be killed...", progress = "I wish there was more I could do to help. I've never regretted it more that I didn't pick up my father's skills in the arcane.", completion = "I hope their souls find peace. I wish it didn't have to be this way.", objectives = "Slay 16 Clessington Attendants in the Defias Hideout in Moonbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72434] = { id = 72434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruby Lifeshrine Loop", description = "They say I'm not big enough to fly some of these courses yet. \n\nBut I can still watch others do it. You should race! Then I can watch you race.", objectives = "Complete the Ruby Lifeshrine Loop course.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72435] = { id = 72435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientation: Iskaara", description = "Welcome to Iskaara, friend.\n\nWord of your exploits in Brackenhide has already spread among our people. You have already met many of us, and there are more who would like the chance to exchange knowledge and wares with you.\n\nPlease, take a moment to familiarize yourself with some of the friendly faces around Iskaara. We are a community that supports one another, so just as you have much to offer us, many of our people have much to offer you in return.", progress = "We have much to offer each other, friend.", completion = "I hope you have a pleasant time in Iskaara. \n\nAs you know now, many us are fine craftsmen and merchants. I encourage you to continue to ask around and learn what all of my people have to offer.", objectives = "Familiarize yourself with some vendors with valuable wares.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72438] = { id = 72438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarasek Intentions", description = "When the tarasek accepted power from the Primalists, they stole many ancient scrolls and tomes to combine with their newfound magic. We need help getting these scrolls back in our possession.", progress = "Have you retrieved any of the scrolls?", completion = "Thank you for helping us recover this valuable knowledge.", objectives = "Gather 15 Draconic Scrolls from the tarasek of the Dragon Isles for Dothenos of the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72440] = { id = 72440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Mettle", progress = "I do not wish to startle the man with my... presence. Perhaps it would be best if you approached him first.", completion = "This place is a monument to Tyr's legacy. We must proceed with caution and reverence.", objectives = "Venture into the Tomb of Tyr with the aid of the Aspects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72441] = { id = 72441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaching the Tomb", description = "Something recently activated the tomb's titan defense system. I had not seen titan constructs here before.\n\nI was investigating why they appeared when I was locked out of the tomb. Perhaps your mission awakened them.\n\nShould we intend to venture forth, we must disarm the new defenses. The glowing orbs flanking the doors might be the key. If only they weren't damaged...", completion = "Your mission has renewed my faith. Now, what must we do to restore Tyr?", objectives = "Disable the Titan Orbs at the entrance to the tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72442] = { id = 72442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Remains of Tyr", description = "As Nozdormu could sense power lingering in the scale, I can sense Tyr here. It is in the very stones of this place.\n\nI suspect the other constructs can sense it as well. They must have come here when Tyr was reforged. We must be on the right track.\n\nIf something of his presence still remains, the scale should be able to gather it--with the help of this console. But the constructs may interpret our collection of Tyr's last memories as us trying to destroy them. \n\nKeep them away if they awaken.", completion = "The task was too great for this aged console, but our persistence has been rewarded.\n\nThe scale has something, but I am not sure what.\n\n I am... uncertain I wish to return to Alexstrasza with just \"something.\" The scale could contain nonsense corrupted by the console's failure. Or it could be what we need.\n\nPerhaps another console could verify its contents?", objectives = "Defend Watcher Koranos from the constructs in the tomb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72443] = { id = 72443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyr's Fall", progress = "There is much we still do not know about Tyr.", completion = "Such nobility even in his final moments. Zakajz used the dragons to taunt him... But did Tyr really know they would betray them? Will Alexstrasza? \n\nThis would be a great blow to them... \n\nIf Tyr cannot be raised, perhaps it is not something they need to know.", objectives = "Use the Titan Console to witness Tyr's final memories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72444] = { id = 72444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sliver of Silver", description = "Tyr's final memories are in our hands. This is not a responsibility to be taken lightly.\n\nLet us take the Silver Scale to Nozdormu in Tyrhold. We will attempt to use the console there to awaken him. \n\nIf he is whole again, there will be much to discuss.", progress = "We will do whatever we must to restore Tyr.", completion = "Thank you, {name}.\n\nI am... disappointed that the Silver Scale was not the answer.\n\nWe may have to resign ourselves to a future without Tyr.\n\nI am not still without hope we may find the disk and restore Tyr. And some part of me believes we may defeat the infinites--and the Incarnates--on our own. \n\nBut some paths, however dark, are fated to be tread.", objectives = "Escape the tomb and return to the Aspects at Tyrhold in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72445] = { id = 72445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northshire", description = "Vanessa's care for her people deserves better than a brotherhood of bandits. I am glad to see them part ways. \n\nAnd as spymaster, I'm in no small part relieved.\n\nNow, Northshire. Peasants can become heroes, there. Perhaps your own journey began in that abbey?\n\nIt's also a strong, defensible position to attack Stormwind from. We cannot let it fall!\n\nHurry, to Northshire!", completion = "We must help!", objectives = "Meet Vanessa, Cecilia, and Shaw in Northshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72446] = { id = 72446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Their Problem?", description = "Good to see you again, recruit. Wish it were in better circumstances.\n\nWhatever this \"influence\" is, anybody with half a grudge now thinks it's worth spilling blood over!\n\nNot to mention all the Defias bandits! And the hired thugs! At this rate, more soldiers from Stormwind will only create more confusion.\n\nFrom what I've seen, you can knock the sense back into most of these people. If they keep fighting you after their eyes have cleared... do what you must. They have made their choice.", progress = "I've seen quite a few things in my days of training new recruits... but this is madness!", completion = "We'll take anyone we can and heal them up. Even if we have to tie some down. \n\nSure hope that magic doesn't have any lasting effects.", objectives = "Defend Northshire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72447] = { id = 72447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greatest of Threats", description = "Powerful djaradin and other creatures threaten both the Obsidian Citadel and the safety of my flight. \n\nThis cannot stand.\n\nHelp secure the area. Seek out and eliminate two of our most powerful enemies.", progress = "Is it done?", completion = "Well done. Your willingness to assist has been noted... and is appreciated.", objectives = "Eliminate two rare enemies within the Obsidian Citadel or Slagmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72448] = { id = 72448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing Our Legacy", description = "I have not worked this hard and come this far to lose the Citadel now! \n\nUnfortunately, new threats have emerged. Can I count on your assistance to deal with them? \n\nHelp secure the area. Seek out and eliminate two of our most powerful enemies.", progress = "Have you taken care of the threats?", completion = "Well done! I knew I could count on you, friend.", objectives = "Eliminate two rare enemies within the Obsidian Citadel or Slagmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72449] = { id = 72449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knock It Off!", description = "We're too late, {name}. \n\nClessington has holed himself up inside the abbey and is spreading the chaotic influence of the amulet all over Northshire! \n\nI don't think most of the people here know the difference between friend and foe, anymore.\n\nThis man seems like the type to have a backup plan. Those agents must have a way to get past Clessington's barrier. Take them out and look for anything useful!", progress = "We must get past the barrier and to Clessington, as soon as we can.", completion = "Hmm, it looks like these might be able to combine, somehow...", objectives = "Collect 4 Barrier Keys off the Leading Attendants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72450] = { id = 72450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Clessington Will", description = "I'm no great mage like my father, but I do know a few of his tricks. \n\nI saw those signets you got off the enforcers. My father's private chambers were locked by a similar magical trinket, which can be broken apart into pieces. \n\nLet me put those signets back together into an arcane key. That should get us past the barrier.\n\nThen... I can only hope we can talk some sense into him.", progress = "I hate that it's come to this...", completion = "I'm sorry, I need a moment. He was not a good man, but... he was still my father.", objectives = "Confront Count Clessington inside Northshire Abbey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72451] = { id = 72451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will to Survive", description = "... So it is done. \n\nI would have liked to have questioned the man more. But the power was too much for him. \n\nWe cannot allow the amulet to end up in anyone else's hands. Claim it, {name}, and we shall ensure its safe return to Stormwind, together.", progress = "Are we done, here?", completion = "I'm tired, {name}. I'm tired of the constant battles. I'm tired of being manipulated, abandoned, and hurt. All of our people are. \n\nI miss the person I used to be. A simple girl who wanted to follow her father's footsteps and help her home in the same stride. The girl who thought that was possible. \n\n \n\n... I suppose I owe you some thanks. You've given me much to think about.", objectives = "Recover the Drakefire Amulet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72452] = { id = 72452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go with Honor, Friend", description = "This mission ended up being far more than any of us expected, {name}, and you did very well. I shudder to think of what would have happened without you here. \n\nSome time back, the King commissioned a set of armor be made. Armor to adorn our greatest heroes. \n\nYou have proven yourself more than deserving of such honor.\n\nMeet me in the Valley of Heroes, {name}.", progress = "You have done much for Stormwind, hero.", completion = "You have done so much for this city. Thank you, hero. \n\nWear this armor with pride.", objectives = "Meet Shaw in the Valley of Heroes in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72453] = { id = 72453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal of the Brotherhood", description = "I should have known. I lost control of the Brotherhood the moment those pardons were offered. Anyone with principle is long gone. \n\nIt's only the brutes left, now. And Duncon Ratsbon was always the biggest brute of them all.\n\nLet's get out of here, {name}. If any of these fools try to get in our way, let's teach them a lesson about standing in the path of a VanCleef.", completion = "It feels odd and yet... this feels a long time coming. \n\nSince fighting the Legion, I've felt distant from the Brotherhood. More aid started to trickle into Westfall, and while it will never be enough... the spark of revolution dimmed.\n\n...Or maybe I'm just getting older.\n \nStill, I once thought of myself as someone who stood up for the people. I made mistakes, I hurt them... but who else do they have? \n\nI need to do better, not for the Defias, but for Westfall.", objectives = "Escape the Defias Hideout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72454] = { id = 72454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Obsidian Hatchling", description = "An egg from the black dragonflight is ready to hatch.\n\nReport to Mother Elion in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Obsidian Oathstone to hatch in a location strong with their flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", progress = "Have you brought the newest hatchling?", completion = "An uncorrupted obsidian hatchling.\n\n<A small smile creeps on Lasztak's face.>\n\nIt has been quite a long time.", objectives = "Collect the Black Dragon Egg at the Ruby Lifeshrine then hatch it at the Obsidian Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72455] = { id = 72455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmth and Comfort", description = "In order for the obsidian hatchling to be comfortable, we must build them a proper nest.\n\nYou will need to build their nest from Obsidian Citadel coal to make sure it is warm and suitable. Secondly, Archivist Edress will be able to assist you in finding something that ties them to their people.\n\nWe will want to gather something from Zaralek Cavern as well, as much of their flight's history is rooted there. Surely somebody in Loamm can help.", progress = "We have the most to learn with this hatchling... I hope she has patience while we improve.", completion = "<Agapanthus looks over to the Obsidian Hatchling's nest, relieved.>\n\nThey will be quite comfortable in their new nest. Well done.", objectives = "Gather supplies for the Obsidian Hatchling's nest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72456] = { id = 72456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tomes Of Trust", description = "Despite securing the upper ramparts of the Obsidian Citadel, the djaradin forces continue to pillage the courtyard. The area is full of priceless historical records! We must act quickly to secure anything that documents the lineage of the black dragonflight.\n\nBoth Wrathion and Sabellian desire this information, so you can curry favor by procuring a tome for each of them.\n\nTravel to the collapsed tower of the citadel. You should find something worth recovering.", progress = "Have you found the tomes?", completion = "Excellent! I am certain both Wrathion and Sabellian will be pleased with your efforts.", objectives = "Recover volumes of the Obsidian Genealogy, and deliver them to Wrathion and Sabellian's quartermasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72457] = { id = 72457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Home-Cooked Meal", description = "Black dragon whelps need to grow up to be big and strong. Our hatchling here seems quite small, so I believe she will require something hearty and nutritious to help her along her way.\n\nRoast duck is not only good for your stamina, but also your brain. I think it would be the perfect meal for our young hatchling.", progress = "Duck is a delicacy local to the Dragon Isles. Did you know we have not found them anywhere else in Azeroth?", completion = "Whelps need a good source of energy to grow. They are voracious!", objectives = "Gather Roast Duck Delight for the Obsidian Whelp. This can be crafted via the cooking profession or purchased from the auction house.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72458] = { id = 72458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tag, You're Anxious", description = "Every whelp needs some playtime to get out their energy. Our new obsidian friend is no exception.\n\nThe hatchlings love playing a good game of tag. See if she would like to play with you!", progress = "Every whelp loves a game of tag!", completion = "She is quite timid, isn't she?", objectives = "Play with the Obsidian Hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72459] = { id = 72459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's a Duck?", description = "I will be honest with you, {name}.\n\nIt has been such a long time since we dealt with the black dragonflight that I could not quite tell you much about them. I do know that they are strong warriors, brave protectors of us all.\n\nRusziona is still quite young, but perhaps we should see how well she does with battle? Take her to practice on some ducks in the Ohn'ahran Plains. Let us see her baseline.", progress = "How did Rusziona fare with the ducks?", completion = "She what?!\n\n<Agapanthus holds his head in his hand and lets out a big sigh.>\n\nYou know? That was insensitive of me. I should know better.\n\nI think we need to go back to the drawing board.", objectives = "Kill 5 Bluebill Waddlers in Primordial Vale with Rusziona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72460] = { id = 72460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Solid Pet", description = "I worry about Ruszi. She is incredibly nervous and insecure, and she jumps at nearly anything! I have never heard of a black dragon so terrified of the world.\n\nI believe the best way for us to build her confidence is to find her a companion. Something sturdy and strong that does not move quickly or suddenly.\n\nThe black dragonflight's charge is the protection of earth. Perhaps a small elemental will suit her well.\n\nSpeak to Lysindra at the pet shop in Valdrakken. She should have something suitable.", progress = "Earth elementals are wonderful first pets. They eat gravel, they do not go very far very quickly, and they can stand against almost anything!", completion = "Look at this wonderful elemental! Hopefully it can help our little whelp build her confidence.", objectives = "Obtain a pet for Rusziona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72461] = { id = 72461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatidaephobia", description = "The time has come, {name}. Her new pet Iggy has been doing wonders for Rusziona's confidence, and now I think she's ready to face her biggest fear.\n\nDucks.\n\nThere is a tauren in the Waking Shores who is an expert at using pets to help heal trauma. I think she might be just what we need.\n\nLasztak and Rusziona will meet you there.", progress = "A large duck still may be too much for Rusziona, but a duckling will be perfect.", completion = "Thank you for what you've done for Rusziona, {name}. She has asked if she can go along with you on some of your adventures. She's confident she'll be safe as long as she's with you.", objectives = "Help Rusziona and Iggy defeat a duck in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72462] = { id = 72462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A People in Need of Healing", description = "It is strange, {name}. Despite the years of peace, I am restless. Despite having the Horde and my son, I am lonely. You feel the same, don't you? I see it in your eyes, and in the eyes of many orcs.\n\nI feel perhaps that while we have found our way on Azeroth, we have lost our way as orcs.\n\nCome with me. I wish to speak with an old friend about these troubles, and I would like you by my side.", completion = "This was meant to be a quiet family visit with Drek'Thar, and perhaps a conversation with Durak about his future. \n\nInstead, we have set off on a path that will affect the orcish people as a whole!\n\nDo not misunderstand me, I think this is the best course of action. It is just surprising how quickly it happened. I am to be a Farseer...\n\nThere is much for us to do. We had best get to it.", objectives = "Travel with Eitrigg to Alterac Valley to discuss the future of the orc people with Drek'Thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72463] = { id = 72463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgar's Cactus Apple Surprise...", description = "<The young orc's last words were a request to deliver these Cactus Apples to Galgar.\n\nWill you honor her request?>", progress = "Oh, hello {name}. What do you have there?", completion = "Why are you delivering these? I asked...\n\nOh no.\n\nNo one is supposed to die over these! I just ask all the young orcs to do this! It's supposed to be easy!\n\nWell... Thanks for delivering them for her I guess. Enjoy your reward...", objectives = "Bring the Bag of Cactus Apples to Galgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72464] = { id = 72464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kosh'harg", description = "The Kosh'harg will be held in Razor Hill. Go'el and Eitrigg are gathering the clans as we speak.\n\nWe will have to part ways for now. You must begin mentally preparing yourself for the om'gora--the rite of honor. It is my task to make sure it is a worthy challenge, even for you.\n\nI will call our wind riders to carry my family to the Kosh'harg. You may travel with them, or meet us there.", completion = "Your om'gora has begun. May the spirits guide you to victory.", objectives = "Travel to the Kosh'harg in Razor Hill and begin the om'gora, the rite of honor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72465] = { id = 72465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of the Land", description = "To earn the blessing of the land, a young orc must learn respect for the spirits that dwell alongside us. If we do not live in balance with the elements and life around us, it can lead to calamity.\n\nI will call to the spirits, and they will guide us to where your aid is needed. It is up to you to complete the task before you.", completion = "Hear me, young one. I am the spirit who protects this place, what your people call \"Thunder Ridge\".\n\nThe canyon below once teemed with life. It could once more, with your intervention.\n\nAid me now, and it will benefit my people and yours.", objectives = "Find the Spirit of Thunder Ridge to learn how you can earn the Blessing of the Land.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72466] = { id = 72466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spirit of Thunder Ridge", description = "Life can only thrive when a delicate balance is maintained. The arrival of your people and the humans was but the first link in the chain that led to desolation.\n\nYou yourself are not to blame, but you can be the force that restores what once was.\n\nDive into the waters below and recover the seeds buried in the silt. They are a memory of the ancient forest that once grew in harmony with my people.\n\nBeware, the elements are not at peace here.", progress = "You return! I trust you have aided the Spirit of Thunder Ridge?", completion = "You have done well, {name}. The spirits sing your praises on the wind.\n\nEventually, Thunder Ridge will flourish into a new oasis, benefiting the people of Orgrimmar and the thunder lizards alike.\n\nYou have earned the blessing of the land.", objectives = "Work with the Spirit of Thunder Ridge to restore life to the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72467] = { id = 72467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of the Clan", description = "To earn the blessing of the clan, a young orc must learn that the clan is only as strong as its members. Prove your strength, and worth, to the living orcs.\n\nSince you were not born into a clan, you must first choose a clan to champion, and be accepted by the clan's chieftain.\n\nThe chieftains have gathered in the barracks. Join a clan, and complete the task given to you.", progress = "The clan representatives are inside the barracks. You must choose one to join.", completion = "Your path has been chosen. Are you ready to proceed?", objectives = "Choose a clan to champion during your om'gora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72474] = { id = 72474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking a Killer", description = "Gor'krosh, the Long Knives, has been terrorizing the Valley of Trials for weeks. Orcs have been going missing, and many of our young trainees have been injured.\n\nThe peons took to calling the mysterious attacker the Long Knives because the few bodies we have found all have long, terrible gashes across their backs. They're terrified, and refusing to work!\n\nWe have no idea who or what Gor'krosh really is, but they are clearly very dangerous. Please, find this monster and end this madness!", progress = "Have you learned anything about Gor'krosh?", completion = "What have you found?\n\n<You tell Kaltunk about the large three-toed print, Karranisha's mention of raptors, the peon witness account, and the bodies with deep slashes.>\n\nSo... you're telling me Gor'krosh is actually a huge, white raptor?!", objectives = "Seek out information about Gor'krosh, the Long Knives, from the residents of the Valley of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72475] = { id = 72475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cornering Gor'krosh", description = "If Gor'krosh is a truly a raptor, you should be able to track it down just like any other animal.\n\nSee if you can find its trail. We know it's been around here recently. Corner it in its lair and end this once and for all!\n\nMake sure you return to Razor Hill straight away once you make the kill. The Farseer will need proof of the deed.\n\nThank you, {name}. May the spirits guide your blade. Lok-tar!", progress = "Do you have the trophy? Have you painted your face with the blood of your kill? You will not receive your blessing until the deed is done.", completion = "<Aggra inspects the blood on your face carefully. Satisfied with what she sees, she nods.>\n\nA clean kill. You have defended the young and the weak honorably. The spirits are pleased.\n\nYou have earned the blessing of the clan.\n\n...You may have your clothes back.", objectives = "Hunt down Gor'krosh and return to Razor Hill with proof of your kill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72476] = { id = 72476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of the Ancestors", description = "The blessing of the ancestors is meant to teach young orcs that the living owe everything to those that came before. We must honor the ancestors, seek their wisdom, and live up to their expectations.\n\nYour task is to craft an offering worthy of the honored dead, and worthy of being the centerpiece at the offering stone of the first Kosh'harg of Azeroth! You must put all of your energy into its construction, or it will not be enough.\n\nCook Torka will guide you. The ancestors will be watching.", completion = "So, the big hero comes to Cook Torka for help, eh? \n\nFine, but you're going to have to do most of the work yourself!", objectives = "Talk to Cook Torka to learn about crafting your offering.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72477] = { id = 72477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcish Groceries", description = "In here is a recipe for the traditional feast left for the ancestors at the Kosh'harg by the clans. We're going to have to substitute some ingredients that, you know, no longer exist... \n\nBut it will for the better! We'll bring some Azeroth flair to this traditional dish!\n\nI will teach you each piece of the recipe, but it will be up to you to gather the ingredients and actually cook it. Orc traders have come from all over, so you should be able to find everything you need right here in Razor Hill.", progress = "Did we find everything on the list? Torka said we could probably find everything in Razor Hill!", completion = "We tracked down everything on our list! \n\nWhat's next?", objectives = "Gather cooking ingredients from traders in Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72478] = { id = 72478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Glory", description = "You have successfully completed the om'gora! Congratulations, {name}.\n\nNow it is time for us to celebrate! We have prepared a feast for all in attendance, in your honor!\n\nGo, revel in the glory you have earned. Enjoy yourself. If any of these orcs get out of line, remind them why you were the one who was chosen to complete the new rite first!", progress = "The Kosh'harg has been a great success, better than I had dared hope. Have you had your fill of the festivities?", completion = "Yes, I think it's time we draw this celebration to a close. There is such a thing as partying too hard!", objectives = "Enjoy the feast!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72479] = { id = 72479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aka'magosh", description = "The Kosh'harg has been a great success, in no small part thanks to you, {name}.\n\nAll that is left is for Aggra to perform the ceremony to bring the festival to an official close.\n\nI wish to speak to the crowd before we all disperse again, on some things long overdue in being said.", completion = "A new age has dawned for our people, {name}. \n\nI could never have imagined bringing you in on my old fool's crusade would have led to this moment.\n\nWe had this armor specially made, just for you. You have more than earned it.\n\nHail, {name}, Champion of the Orcs!", objectives = "Observe the formal closing of the Kosh'harg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72481] = { id = 72481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waking Shores Tour", description = "And what is the most fun about dragonriding? Races! \n\nMy bronze colleagues have mapped out race courses all over the Dragon Isles. It is such a varied and dynamic landscape that it just begs to be explored at top speed.\n\nIf you find yourself near one of our race courses in The Waking Shores, why not give it a go?", completion = "Well done! You are getting a handle on dragon racing just as quickly as I thought you would. \n\nAnd that was just the beginning. Next up is the Ohn'ahran Plains!", objectives = "Fly each of the race courses in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72482] = { id = 72482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waking Shores Advanced Tour", description = "Now that you've flown the basic courses all over the Dragon Isles and proved your ability, how about a new challenge?\n\nThe advanced race courses are similar to the standard courses you have flown, but many have adjusted flight paths or extra obstacles to test your skill.\n\nLet us start with the courses in the Waking Shores!", completion = "Nicely done! Those obstacles sting a bit when you first hit one. But you powered through and completed all the courses!\n\nNow! I bet you can guess what is up next. Races in the Ohn'ahran Plains!", objectives = "Fly each of the advanced courses in Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72483] = { id = 72483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ohn'ahran Plains Tour", description = "Ah, the Ohn'ahran Plains. Wide open spaces, gusting winds, endless vistas... and more race courses!\n\nJust as in the Waking Shores, if you find any of my bronze colleagues, speak to them about their race course.", completion = "Excellent flying, {name}! Your control of your drake shows how far you have come as a dragonrider. \n\nAnd such speed! I trust now you know how truly freeing it is to fly like a dragon!\n\nNow! There are more places to see and more races to run. Next stop: the Azure Span!", objectives = "Fly each of the race courses in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72484] = { id = 72484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ohn'ahran Plains Advanced Tour", description = "The advanced courses should be more challenging, but I am sure it is nothing you cannot handle!\n\nMy bronze colleagues have set up advanced courses in the Ohn'ahran Plains that have a few obstacles and surprises thrown in them. You can also compete against your own best times!\n\nGood luck!", completion = "Well done! You are just like a whelpling taking to air or a duck taking to water as one might say. \n\nNext, we will conquer new challenges in the Azure Span!", objectives = "Fly each of the advanced courses in Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72485] = { id = 72485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Span Tour", description = "Azure Span courses are a unique experience. Their high peaks, snowy terrain, and dense forest present plenty of interesting obstacles--and challenges!\n\nWhile you are there, seek out my bronze colleagues and give their courses a try!", completion = "Good show, {name}! Nimble work completing the Azure Span courses... \n\nAnd barely a scratch on you! It seems like the trees there jump out in front of me all the time...\n\nNext up, we are on to Thaldraszus--for more races, of course!", objectives = "Fly each of the race courses in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72486] = { id = 72486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Azure Span Advanced Tour", description = "The advanced courses in the Azure Span are designed to elevate your dragon riding skills to new heights! \n\nJust... make sure you don't fall from them!\n\nWhen you're ready, seek out my bronze colleagues and fly those courses!", completion = "Nicely done! You have almost mastered all of the advanced race courses in the Dragon Isles!\n\nNow! On to Thaldraszus and the last set of challenges!", objectives = "Fly each of the advanced courses in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72487] = { id = 72487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thaldraszus Tour", description = "Thaldraszus. It is the home of the Seat of the Aspects and much of dragonkind's history. \n\nIt is also home to soaring heights and steep deep ravines just waiting to be flown over!\n\nAs before, my bronze colleagues have set up race courses in Thaldraszus to fly while you explore. \n\nWhy not give them a try and complete your Dragon Isles racing tour?", completion = "Fantastic! You have raced your way all over the Dragon Isles. This is irrefutable proof of your skill as a dragon racer!\n\nEven so, I can see even more challenges and advanced courses await you in the future!\n\nBut for now, congratulations!", objectives = "Fly each of the race courses in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72488] = { id = 72488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thaldraszus Advanced Tour", description = "Once more to Thaldraszus with its peaks and valleys and courses ready and waiting for you to race!\n\nSeek out my bronze colleagues to fly the advanced courses and finish your racing tour of the Dragon Isles!", completion = "You did it! You've flown all of the advanced race courses all over the Dragon Isles. I am immensely pleased--and impressed! \n\nFeel free to re-fly any of the courses to beat your own best times. The sky's the limit!", objectives = "Fly each of the advanced courses in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72510] = { id = 72510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/1" }
quests[72512] = { id = 72512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Whispering Breeze", description = "<Godoloto cocks her head quizzically, nods at you, and finally holds your gaze. After a long moment, she casts her eyes up towards the sky... and the mountain just beside Maruukai. You sense that she wants you to travel up to Ohn'ahra's Roost.>", progress = "<Ohn'ahra looks at you appreciatively.>", completion = "<As you approach, the great ohuna spirit settles on the ground and gazes at you. Gently, she lowers her head to touch your forehead with her own. In that moment, a comfortable warmth spreads within you. The winds are now within your reach.>", objectives = "Approach Ohn'ahra in Ohn'ahra's Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72513] = { id = 72513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Destiny", description = "Evoker! You might have felt a disturbance just recently.\n\nEbyssian and I have begun to unbind the ancient siphons that were extracting the black dragonflight essence from dracthyr. I suspect that only the fully trained evokers like yourself are tuned enough to feel the change.\n\nThere is more, though. Please, come join Ebyssian and myself at the High Creche in the Forbidden Reach. We have a dragon to unchain.", completion = "{class}, stand to. We may have a situation.", objectives = "Speak with Scalecommander Emberthal at the High Creche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72514] = { id = 72514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Creche", progress = "The vindictiveness of this trap... how could we have been so blind to Neltharian's cruelty?", completion = "Well done. We will need Ebyssian to sunder the last strand of magic sustaining this imprisonment.", objectives = "Disrupt 4 Essence Collectors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72515] = { id = 72515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augmenting a Dragon", description = "Adamanthia!\n\nShe has been imprisoned for ages, trapped in torment. While the dracthyr slept, she suffered.\n\nI can only hope she has not given in to Deathwing's madness during her long imprisonment. The passage of time may have shattered her mind.\n\nBe ready, champion. Should she lash out, aid Ebyssian. Augment his abilities, so he can subdue Adamanthia instead of slaying her.\n\nShe has earned a chance. We must give it to her.", progress = "Adamanthia has waited long enough for this day. Let us hope it has not come too late.", completion = "We... are good.\n\nI think... she will be okay after this. Thank you, {class}. Now we can get Adamanthia the help and healing she needs, so we can welcome her to this new world.", objectives = "Help Ebyssian subdue Adamanthia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72519] = { id = 72519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporal Two-ning", description = "I see... They are falling through possibilities as well as time.\n\nHurry, I have located another point in the timeline where we might catch them. It is... unusual, but do not let the strangeness of this world slow you down. Chronormu's fate is in your hands.", completion = "The process was not finished but I can more accurately track Chronormu now.", objectives = "Use Chrono Crystal on Eternus and Chromie in Azmerloth to stop them from falling through time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72524] = { id = 72524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Climbing Gear", description = "<Pathfinder Jeb motions to the supply kit next to him.>\n\nYou're going to need supplies to survive out there.\n\nLet's get you what you need to start climbing.", completion = "This basic equipment will get you started.\n\nCome back when you have more Dragon Isles Supplies to get trained in new gear.", objectives = "Use the Expedition Supply Kit to research Climbing Gear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72525] = { id = 72525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Cataloging Gear", description = "Every expedition cataloger deserves their very own camera!\n\nYou don't need to give yours a special name, but I highly encourage it. It's far more fun.\n\nAnyway, Pathfinder Jeb should be able to get you everything you need.\n\nI've yet to need a single thing that he hasn't brought along with him. He's incredible!", completion = "Oh, your new camera is beautiful. It matches you perfectly!", objectives = "Use the Expedition Supply Kit to research Cataloging Gear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72526] = { id = 72526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper's Rest", description = "I do not enjoy seeing others forged by Tyr disabled. They went through such effort to keep the tomb from collapsing, and now it will languish devoid of even what was left of Tyr's light.\n\n<Koranos gestures to the Silver Scale.>\n\nI hope whatever is in the scale is worth their destruction. Let us find another console to see what, if anything, is on the scale.", progress = "We act in the service of Tyr. He would understand.", completion = "We are safe for now, but we should not linger.", objectives = "Escape to the Darkwalk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72527] = { id = 72527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Such Thing as Bad Luck", description = "Look, believe it or not, I'd be in the Isles already if it wasn't for unfinished business. Recent events have not been kind to me. I owe the Baron, and nobody owes the Baron for long. He will absolutely find and skin me if I don't pay up.\n\nI invested his money in these magic crystals, but their price just crashed on the market because of the front page ripper in the Booty Bay Journal. And the shipment of crystals is missing!\n\nSomeone must be plotting my demise. Perhaps the Goodstitches will help me.", completion = "...I shouldn't be surprised that no one will help me for free. Ask Blixrez his price.", objectives = "Find Blixrez Goodstitch in Tan-Your-Hide Leatherworks in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72528] = { id = 72528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revival Catalyst", description = "The catalyst is a powerful artifact capable of great feats of empowerment. \n\nAs you go forth with your allies and give battle to the greater threats of this land, bring back any Renascence you find. With it, we can power the catalyst to imbue your equipment with the wisdom and might of Tyr himself.", completion = "Ah! A marvelous collection of ideas and concepts. So much has changed, and so much has not.", objectives = "Gather Renascence from group content throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72529] = { id = 72529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Information is King", description = "Information ain't cheap. Outta everyone, Zeros should know that best.\n\nPeople have sighted dangerous crocolisks around Janeiro's Point. You know what I see? Money, money, money! Get me their precious skins and maybe I'll remember something important about those crystals Zeros is after.\n\nIf that's too dangerous for your cup of tea, I might be open to other forms of payment too. You know, the most common form.\n\n<Blixrez folds his arms and waits expectantly.>", progress = "Friendship is like a scale. It must remain balanced at all costs!", completion = "Mmhm, this will do!", objectives = "Collect 3 Crocolisk Skins in Janeiro's Point, or give gold to Blixrez Goodstitch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72530] = { id = 72530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anyway, I Started Bribing", description = "The scoundrel! I had a deal with Arty to market the crystals in the paper. Someone must've cut a bigger deal with him.\n\nArty routinely inspects the Venture Company's working area on the shore. He always brings his own guards, but no one is immune to gold in Booty Bay.\n\nTake my last bit of gold. Go to the oil rigs and bribe the guards to look the other way before you confront Arty.", progress = "That's all the gold I got, so if you need to throw in some punches to sweeten the deal, be my guest.", completion = "Pirates?! Of course. We know where to go next.", objectives = "Use the gold to bribe Arty's Hired Bodyguards and then confront Prospector Arty in Wild Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72532] = { id = 72532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Money, Money, Money!", description = "Grub Redcut and his crew are notorious for their love of money. They'll do anything for it.\n\nI assume there is treasure to be had on his own ship, but just in case there isn't, there must be gold within their pockets. Will you do me the dirty business of collecting it?\n\nI won't question your negotiation tactics--just don't kill them! I'm not trying to start a serious blood feud today.", progress = "It's high time those pirates learned they can't terrorize anyone they please.", completion = "Oh my gold, that looks like a hefty sum.", objectives = "Collect 1500 Gold Coins from Grub Redcut's pirates in the Southern Savage Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72533] = { id = 72533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals Shmystals", description = "Grub. Redcut. <Zeros spits.> A sore, crusty loser, who thinks he's all tough because he's big and buff. He hates that someone like me can make more money than him.\n\nBelieve it or not, I play the auction house fairly. I'm a saint compared to him!\n\nSo Grub sold my crystals, eh? And then paid Arty to lie about them so no one would go looking for them. A fine plan.\n\nGrub must have something valuable on that ship of his. Well we're going to go take it. Search the ship thoroughly.", progress = "Please hurry! The Baron wasn't kidding about my scales--I'm a dragon, as you know, and my scales are worth quite a lot.", completion = "What did you bring back?", objectives = "Retrieve Grub Redcut's treasure from his ship in Southern Savage Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72534] = { id = 72534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Settled with the Baron", description = "Ha...! You returned just in time. A minute later and you might've found a skinned dragon on your hands.\n\nGive him the treasure, quickly.", progress = "Give him the gold already, will you? Please!", completion = "Senegos! You just saved my life.", objectives = "Give the treasure to Baron Revilgaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72535] = { id = 72535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (60-69) E" }
