quests[72545] = { id = 72545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creche Fallen", progress = "Hmm? Sorry. My thoughts are... elsewhere, right now.", completion = "<Emberthal gives you a solemn nod.>\n\nThank you, {name}.", objectives = "Collect the Horn Signet of Tetsos, Horn Signet of Arrosh, Horn Signet of Ekrati and Horn Signet of Hermin in the Lost Atheneum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72546] = { id = 72546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Academic Assistance", description = "{name}! I've made a breakthrough with tha Winterpelt dialect. Ya helped get tha ball rollin' on this, so I felt like I ought ta keep ya apprised of the situation.\n\nMeet me in Theron's Watch and I'll tell ya all about it.", completion = "Good to see ya again, {name}.", objectives = "Meet Sonova Snowden in Theron's Watch.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72547] = { id = 72547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Academic Acquisitions", description = "I'll head up tae the village an' give 'em the bad news--or try. Winterpelt's a right tricky dialect tae learn.\n\nI need ye tae get out there an' find me some furbolg writin' samples tae study if we ever hope tae communicate properly.\n\nThe Primalists've wiped out or converted most o' the remainin' furbolg in the Span, so go shake 'em down until whate'er cultural artifacts they have drop out.\n\nI'll need at least five tae start, but bring me as many as ye can, and I'll keep teachin' ye what I learn.", progress = "What've ye got for me?", completion = "Not a bad start, {name}.\n\nI'm goin' tae need a lot more if we ever want to have a conversation, though!", objectives = "Recover furbolg artifacts from Primalists in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72548] = { id = 72548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (60-69) E" }
quests[72549] = { id = 72549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (60-69) E" }
quests[72550] = { id = 72550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (60-69) E" }
quests[72551] = { id = 72551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Living History", description = "The Winterpelt finally trust us enough to ask for aid.\n\nWe must nurture this trust so we may one day clasp their paws in friendship!\n\nThis Winterpelt, Jyrra of the, uh, Fuzzy Feet, says their elders went into hiding during the Primalist attack on their village. I don't yet understand their language, but it seems the elders left markers to help the clan find them later.\n\nIt's time to let the Winterpelt elders know it's safe to come home. Will you convey this message? It seems a simple enough task.", completion = "Wait... is it true? You've come from our village? \n\nHas the fighting stopped?", objectives = "Follow the markers to find the hidden Winterpelt elders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72552] = { id = 72552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Together", description = "I haven't heard an outsider speak our tongue. Your grasp is a bit basic...\n\nBut only a friend of the clan would speak it at all!\n\nI am Elder Mhaz. If it is safe to return home, we should set off soon. But many of us are weak with sadness of the heart--and grumbling of the stomach. I would not put you at risk gathering fresh meat, but could you gather roots for us? \n\nWe have already gathered ones that are close. I hope this comfort food will lift our spirits enough to return!", progress = "The roots grow around the bases of the large trees. We have not ventured east because there are many worms. Perhaps there are more there?", completion = "I'm glad to see you have returned safely!", objectives = "Gather 8 roots for Elder Mhaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72553] = { id = 72553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Effort, More Reward", description = "We're not sad. We're starving. That's the truth of it. A few tasty roots won't be enough.\n\nElder Mhaz doesn't recognize strength, but I do. It should be (100)-trivial for you to bring us some fresh meat! The worms to the east should be easy prey.\n\nPlease, bring back what you can carry!", progress = "Worm meat should be easy enough. Pick on the little worms if you're not up for the bigger ones.", completion = "I knew I was right about you, {class}.", objectives = "Collect 12 pieces of meat from worms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72554] = { id = 72554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Him", description = "You handled those little worms with such ease!\n\nHowever... Saza hasn't come back. The giant worm, Icebreaker, has been hunting us for weeks. It took two of our elders while we gathered food and injured me when I tried to avenge them. And now, with Saza missing, I fear the worst.\n\nFind Saza, and get rid of that worm!", completion = "So. It was Icebreaker?\n\n<Matron Fherg cries out in a mournful howl.>\n\nOur bright, brave cub... Oh, Saza...\n\nAnyone here would gladly give up their lives in trade for Saza's. Icebreaker's death brings some comfort, but it will not bring her back. \n\nSaza's loss will be felt by all of us.", objectives = "Find Saza and kill the large worm, Icebreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72555] = { id = 72555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[72556] = { id = 72556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[72557] = { id = 72557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflight (70) E" }
quests[72558] = { id = 72558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Honored Ancestors", description = "It is time to take the next step to understanding the Winterpelt. That step is a spiritual one. \n\nThey look to their ancestors for advice as they choose their path forward. We can learn from them too.\n\nBut the Winterpelt rite to call their ancestors is... intricate. And long. \n\nIt would be rude to copy their ritual anyway. We'll do it our way with Rustpine Spiritspeaker incense.\n\nCome! Let us reveal their ancestors' wisdom and learn more about our new friends!", progress = "When you're ready, the incense will allow you to see spirits.", completion = "Can you see them?", objectives = "Use Radza's incense to allow spirit sight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72559] = { id = 72559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "History Heist", description = "When the Primalists raided our village, they took more than our lives; they stole the heart of our community--our priceless historical documents! \n\nI will not stand for records of our traditions, rituals, and rich history taken from us! We still have lessons to learn from them.\n\nPlease, recover them from those looting Primalist scouts so they can be preserved!", progress = "Did the ancestor send you on a mission?", completion = "These pieces are incredible! What a horrible loss this would have been to the Winterpelt.", objectives = "Find the stolen Winterpelt \"documents.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72560] = { id = 72560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Climbing" }
