quests[72640] = { id = 72640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Ah, our paths meet again, {name}. I am glad you have returned to us safely. Your deeds have made you honored among the Iskaara. Please, take these supplies as a token of our thanks!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72641] = { id = 72641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", objectives = "Ah, our paths meet again, {name}. I am glad you have returned to us safely. Your deeds have made you honored among the Iskaara. Please, take these supplies as a token of our thanks!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
