quests[72644] = { id = 72644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Urgent Matter", description = "Hello {name}. I was told to give you letter. The messenger mentioned it was urgent.\n\nThe crest on it seems to be from SI:7. I would read it right away if I were you.", completion = "It's good you are here.", objectives = "Meet Master Mathias Shaw on the outside ramparts behind Stormwind Keep.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72646] = { id = 72646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of Life: The Waking Shores", description = "Cannae ya smell the sweet scent of adventure on the wind?\n\nThe Waking Shores are close ta bursting with energy and life right now. Get out there and claim a piece for yourself!", progress = "I hear the Life Pools are lovely this time of year.", completion = "Did you find anything of value?", objectives = "Collect 100 Sparks of Life in the Waking Shores, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72647] = { id = 72647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of Life: Ohn'ahran Plains", description = "The Ohn'ahran Plains are overflowing with energy, {name}, and the lands teem with beasts.\n\nNow is the time to join in the hunt, to revel in the bounty, and earn glory for yourself.", progress = "How goes the hunt?", completion = "Glorious, was it not?", objectives = "Collect 100 Sparks of Life in the Ohn'ahran Plains, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72648] = { id = 72648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of Life: The Azure Span", description = "The tides have come in, and they've brought a bounty of life with them to the Azure Span.\n\nIt's a time for friends, family, good food, and forging new stories.", progress = "Do try the soup while you're out.", completion = "Run into any gnolls?", objectives = "Collect 100 Sparks of Life in the Azure Span, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72649] = { id = 72649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of Life: Thaldraszus", description = "Thaldraszus is thrumming with the renewed energies of the Dragon Isles.\n\nGet out there and take advantage of it.", progress = "Right out that door. Can't miss it.", completion = "The Accord thanks you, no doubt.", objectives = "Collect 100 Sparks of Life in Thaldraszus, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72650] = { id = 72650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warm Winds and Water", description = "Kirygosa wrote me after leaving Stranglethorn some years ago. She said it was beautiful and balmy, but not very quiet. I presume--and hope--she has found peace in Pandaria.\n\nIf I am honest with myself, I should not be surprised that she hasn't answered the Isles' call. Yet, we must do our duty and seek her out. If I am doubly honest with myself, I would have any excuse to see her again.\n\nLet us take a break from these chilly winds and visit the Jade Forest.", completion = "...Kalecgos?!", objectives = "Find Kirygosa in The Jade Forest in Pandaria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72651] = { id = 72651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carp Care", description = "The village carp bring fortune and peace. Their well-being reflects the health of the village.\n\nThe carp thrive on special food made from worm meal and vegetable paste. It's not as unpleasant as it sounds, especially after we finish dehydrating it into neat little blocks.\n\nHere! Just toss it gently in the water near them.\n\nTheir ponds also require cleaning, so please skim any debris you find.", progress = "Have you finished feeding the carp?", completion = "All done? Thank you. The carp are so pretty, aren't they? Their scales shimmer almost like a dragon's.", objectives = "Feed the carp and clean their ponds of debris in Dawn's Blossom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72652] = { id = 72652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Self Care", progress = "<Kalecgos is paying deep attention to Kirygosa.>", completion = "Oh--did you finish? Thank you very much. I can tell Kiry appreciates you.", objectives = "Tidy Kirygosa's home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72653] = { id = 72653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Local Deliveries", description = "I've been cultivating a new flower in this land. It's quite versatile, but the villagers and I are still refining its various uses.\n\nI just harvested my latest batch today. Will you help me deliver them?", progress = "Have you met my neighbors yet? Don't be shy about introductions. Everyone is pleased to meet outsiders that respect our traditions and way of life.", completion = "Wonderful! By the way--if you like the flowers, I would love to give you a bunch from my next harvest.", objectives = "Deliver Wild Blue Yonders to villagers in Dawn's Blossom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72654] = { id = 72654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up, Up, and Home", completion = "Here we are.", objectives = "Fly with Kirygosa to her home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72655] = { id = 72655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Drink with Kalecgos", description = "<Kalecgos is quiet for a moment, a wistful look on his face.>\n\nI'd call upon Nozdormu to help us pass the time, but he'd tell me that I should be able to handle this.\n\nSo... the Drunken Hozen. If Kiry recommends it, then let us go!", progress = "Peiji Goldendraft recommended the perfect brew for comradery. Hot barley tea! Please, have some.", completion = "This respite was much needed.", objectives = "Have a drink with Kalecgos in The Drunken Hozen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72656] = { id = 72656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterspring", description = "Haleh, Matron Protectorate, presides over Winterspring. Even after defeating the power hungry mage Umbranse, she continues to find and dispel danger in her homeland. As the last living consort of Malygos, she tirelessly upholds his legacy as a guardian of magic.\n\nHer return would greatly strengthen the blue dragonflight.", completion = "I have been keeping tabs on Haleh since my awakening.", objectives = "Speak to Sindragosa for more information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72657] = { id = 72657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Protector of Magic", description = "I am very curious about Haleh--she is one of the last living consorts of Malygos. I am grateful for her going to Malygos in his time of need.\n\nI will admit, I have spent some time spying on her. She is a blue dragon through and through. Studious, proud, and one of the more careful ones around magic. \n\nI do feel most suited to be the one to visit her about the call of the Isles. Take my portal when you are ready. I shall meet you there.", completion = "Name yourself, intruders!", objectives = "Find Haleh in Winterspring in Kalimdor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72658] = { id = 72658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flightstones", description = "You caught my eye from the moment you stepped foot in Loamm, champion! Look at all that sparkling gear. And I can sense you want... more.\n\nYou may have stumbled across Flightstones already. My friend Cuzolth and I know how to harness the power of Flightstones to upgrade gear.\n\nWe have shared the knowledge with our network of upgrade specialists. Any of them will be able to tell you exactly what you need. Cuzolth can show you now, provided you have enough Flightstones.", progress = "More powerful gear opens the door to more exciting adventures! Isn't that what we live for?", completion = "Your gear glitters a little more brightly, champion! I am always seeking to make our community stronger.\n\nPlease, accept these gifts.", objectives = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth, and upgrade a piece of equipment using Flightstones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72659] = { id = 72659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test Subject", description = "Today is day forty-one without finding a harmful artifact. I am further delighted to report that while you were away, a handful more proved harmless. Perhaps my hunt in Winterspring is almost concluded!\n\nCome to think of it... you have some magical ability, don't you? Or enough bravery to help me test some more artifacts?\n\nDo not be nervous. None of them will permanently hurt you. Artifacts with that kind of dangerous power were taken care of in my first year here.", progress = "Do take your time, {name}... there are only hundreds more to go.", completion = "It seems three out of three were of little magical impact. This is truly great news.", objectives = "Test the artifacts Bottled Spirit, Icy Book, and Left Boot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72660] = { id = 72660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Owl of a Sudden", description = "While you were working, I was inspecting the totemic ruins you retrieved. There has always been something odd about the Hidden Grove. It used to be occupied by a robust population of harmless white hares. Now there are only maddened owlkin and strange totems...\n\nI put the pieces together. It is no masterpiece, but hopefully we can glean a stronger magical effect from the whole.\n\nMaybe it will even make us sprout some feathers and fur. You would think as a blue dragon I would enjoy the cold, but no.", progress = "I cannot remember the last time I had proper help. Thank you.", completion = "Of course, what did I expect?", objectives = "Test the Restored Owlkin Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72661] = { id = 72661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wyrm Rest", description = "Oh dear. I have an idea. Speak to me when you are ready.", progress = "I fear Haleh has not been getting adequate rest.", completion = "Sometimes we just need a taste of the simple things again.", objectives = "Work with Sindragosa to cheer up Haleh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72662] = { id = 72662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying Supplies", description = "The Nokhud have been striking at outsiders crossing into the plains. This is no doubt their handiwork.\n\nThis survivor says that most of their food supplies were destroyed in the ambush. We should try to help out.\n\nLet's collect meat from the plentiful game around the Watering Hole. That should be enough to cover their immediate needs.", progress = "How much have you collected?", completion = "Good, this should be plenty.", objectives = "Collect 40 Fresh Plains Meat from the area surrounding Toghusuq Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72663] = { id = 72663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinewood Trail", description = "If Bovan is not dead, and he is not here, then either he is still out there... or he has been captured. Given Tomul's message, I fear it's the latter.\n\nThe Windtotem are safe for now, but with an attack possible at any moment, they can't spare any braves to go after Bovan.\n\nIt looks like it is up to us. Let us head to Pinewood Post.", completion = "Tomul wanted me to wait for you in her encampment, but I... politely declined to do so.", objectives = "Meet up with Tomul and Baine at Pinewood Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72664] = { id = 72664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eggs in Abundance", completion = "Thank you for coming, {name}. Soon the whelps will greatly outnumber us.", objectives = "Meet Amella at the Ruby Lifeshrine in the Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72665] = { id = 72665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelptender's Wisdom", description = "Our egg-tenders report a new clutch of eggs is soon to hatch. Ordinarily, a whelptender would take each newly hatched dragon and raise them with their flight. However, not all dragonspawn are called to the life of a whelptender, and we are short of hands.\n\nGather wisdom from whelptenders of each flight in the gardens below the Lifeshrine. Agapanthus, an experienced whelptender of the blue flight, has offered his services as head of the Little Scales Daycare. But he will need your assistance.", progress = "Whelptenders of the red flight study the methods of each flight to provide the best all-around care. It makes sense that you are studying those methods, too.", completion = "Amella said to meet you. I have been assigned to help Agapanthus with the daycare.", objectives = "Speak to whelptenders at the gardens of the Ruby Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72666] = { id = 72666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daycare Director Agapanthus", description = "Amella has told me about the incoming whelps and about the daycare. Did you know Agapanthus is a renowned whelptender? I heard he fought back demons while rearing whelps! \n\nIf he's as amazing as they say, I have much to learn from him. I only just received my Calling, but I will help in any way I can.\n\nThe Little Scales Daycare is in Valdrakken. I will gather my things and meet you and Agapanthus there.", completion = "Lasztak has just informed me of his rigorous study as a whelptender of the red flight. Most of my experience is hands-on. And you...\n\n<Agapanthus sighs and scratches his chin.>\n\nWe will have to develop curriculum.", objectives = "Meet Agapanthus at the Little Scales Daycare in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72667] = { id = 72667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snack Run", description = "The whelps that visit the daycare eat snacks during their visit. A lot of snacks.\n\nIf there are going to be whelps that stay here with regularity, we will need even more rations to sate their endless hunger.\n\nHere is a list of snacks the whelps have taken to lately. I also ordered something for Sir Pringly, so be sure to get that as well.", progress = "It was the same in Aszuna. Cheese and crackers are treasured by all whelps.", completion = "That was a remarkable first snack run, {name}. Hopefully these snacks continue to be to the whelps' liking.", objectives = "Gather snacks from vendors in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72668] = { id = 72668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nurturing Environment", description = "Young whelps can be careless in how they treat their space. The daycare is effectively under siege day in and day out!\n\nHelp clean up the daycare. The new whelps will need a proper place to stay.\n\nI will not let one claw set down on unpolished stone or overgrown grass!", progress = "Is there anything better than squaring away a space?", completion = "This should do for your first sweep of the daycare. Good work, {name}.\n\nI believe our curriculum is off to a good start. Now we must await the whelps.", objectives = "Help put the Little Scales Daycare back into order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72669] = { id = 72669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72670] = { id = 72670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those We Left Behind", description = "In attempting to defend their home against the fury of the blue dragonflight, Shandaral's mages condemned the souls of their people to an eternity of crystalline torment. \n\nNow their echoes wander aimlessly, reliving their civilization's doom again and again for more than ten thousand years.\n\nI have found that some of the shades yet retain a shred of sentience. Perhaps they can be reasoned with--convinced to free themselves from the mire of their own ancient fear and pass on at last.", completion = "This crystalline prison is not easy to escape. Still, with luck our work here will let the spirits that yet linger find some modicum of peace.", objectives = "Ease the restless echoes of Shandaral.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72671] = { id = 72671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72672] = { id = 72672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72673] = { id = 72673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72674] = { id = 72674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Legacy", description = "Shandaral's reckless use of the crystal focus placed too much stress on the relic, causing it to shatter. Its fragments have been scattered amidst the crystalline permafrost.\n\nI can recreate the focus, but I will need you to collect enough of those shards to give me something to go on. You should be able to find them amidst the piles of crystal refuse scattered throughout the area.\n\nTake heed, {class}. Those shards may still hold fragments of the mages's memories from that fateful day.", progress = "Malygos's rage fed Shandaral's desperation. Now our flight's failure is frozen in crystal for the world to see.", completion = "Malygos believed that we alone were capable of stewarding the myriad truths of the arcane. His--and our--failure to consider the potential of mortals led to the tragedy you see here.", objectives = "Retrieve the fragments of the Crystal Focus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72675] = { id = 72675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/2" }
quests[72677] = { id = 72677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/3" }
quests[72678] = { id = 72678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 1/4" }
quests[72679] = { id = 72679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Arcane Requiem", description = "The time is upon us, {name}. With your help, most of the restless echoes of Shandaral have been quelled. However, some yet remain whose rage and sorrow burns too brightly to be eased by mere words.\n\nUsing the shards that you recovered, I have managed to recreate a facsimile of the crystal focus that brought Shandaral to ruin. Using it here should bring the anchored spirits to bear and give us an opportunity to grant them final rest.\n\nBe on guard. I do not know how their long-held sorrows will manifest.", progress = "This will not be a happy ending--but it will be an ending all the same.", completion = "At last, the magic that was binding these tormented memories to this ruin has been broken.\n\nIt will be some time before the lesser echoes fully dissipate. Still, with their source finally banished and the relic's fragments removed, the fragments of memory that remained trapped here will finally be relieved of their torment.", objectives = "Grant the echoes of Shandaral their final rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72681] = { id = 72681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", completion = "Hope ye like this month's collection of new and exotic wares, {name}.", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[72682] = { id = 72682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renown Supplies", objectives = "Greetings, {class}. You've proved your worth to the Valdrakken Accord. Here are some supplies to help you aid our cause. Don't let us down!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
