quests[72686] = { id = 72686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm Surge", description = "{name}, the Primalists have managed to summon fierce Elemental Storms all across the Dragon Isles. \n\nWhen a storm is active go to it and slay the imbued creatures there. \n\nThen collect the Elemental Overflow from the slain foes. Be aware that the stronger the foe, the more Elemental Overflow you will collect.\n\nWe must not let the Primalist elemental corruption grow unchecked.", progress = "Have the storms subsided? Have you brought me what I need?", completion = "This is but a drop in the bucket. \n\nYou would do well to continue to slay the imbued creatures and prevent them growing in strength.\n\nNow I must return to my studies, {name}.", objectives = "Defeat Elementally Imbued creatures to collect Elemental Overflow while in an Elemental Storm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
